  'tour.action.assistant': 'Abrir o assistente',
  'tour.action.accessibility': 'Abrir Configurações → Acessibilidade',
  'tour.step.welcome.title': 'Boas-vindas ao Foreman',
  'tour.step.welcome.body': 'Rode agentes de programação em paralelo, cada um no seu próprio branch, na sua própria cópia do repositório. Tudo fica neste computador. Veja onde estão as coisas.',
  'tour.step.addRepo.title': 'Adicionar um repositório',
  'tour.step.addRepo.body': 'Abra uma pasta que já seja um repositório git, clone um do GitHub ou use o Início rápido para criar um novo. Clique com o botão direito em um repositório para ver as configurações: script de configuração, script de execução e verificações.',
  'tour.step.addRepo.where': 'o botão + na faixa de ícones de repositórios',
  'tour.step.newWorkspace.title': 'Iniciar um espaço de trabalho',
  'tour.step.newWorkspace.body': 'Cada espaço de trabalho é um branch novo em seu próprio worktree, com portas e terminal próprios, então os agentes nunca se atrapalham. Pressione {key} e descreva a tarefa; imagens também funcionam.',
  'tour.step.newWorkspace.where': 'o botão Novo espaço de trabalho, perto do topo',
  'tour.step.needsYou.title': 'Precisam de você',
  'tour.step.needsYou.body': 'Com vários agentes rodando, você deixa de vigiá-los. Tudo o que espera por você (uma aprovação, uma pergunta, um plano, um turno com falha) fica reunido aqui e no Início, com contagem, notificação e um selo na bandeja ou na barra de menus. {next} vai para o próximo espaço de trabalho que precisa de você; {jump}, para o que precisa de você no chat atual.',
  'tour.step.needsYou.where': 'os filtros Todos, Precisam de você, Em execução e Fixados',
  'tour.step.layout.title': 'Duas formas de ver seu trabalho',
  'tour.step.layout.body': 'Três painéis mostra um espaço de trabalho com suas alterações e o terminal ao lado; é o que você tem agora. Blocos mostra os chats de vários espaços de trabalho lado a lado. Mude quando quiser com {palette} («Mudar para blocos») ou em Configurações → Aparência → Layout da janela.',
  'tour.step.automations.title': 'Modelos e Automações',
  'tour.step.automations.body': 'Modelos são prompts com lacunas para os detalhes; mantenha os seus ou os do repositório. Automações executam um modelo em um agendamento (diário, semanal etc.) enquanto o Foreman estiver aberto, com um calendário do que rodou e do que vem a seguir.',
  'tour.step.automations.where': 'Automações, no topo da barra lateral',
  'tour.step.assistant.title': 'Pergunte ao assistente',
  'tour.step.assistant.body': 'Não sabe onde algo fica? Pergunte aqui ({key}). Ele aponta a configuração exata e nunca muda nada. Ele roda no Claude, então entre primeiro no Claude.',
  'tour.step.assistant.where': 'Assistente, abaixo de Automações',
  'tour.step.settings.title': 'Configurações',
  'tour.step.settings.body': 'Acessibilidade: tamanho do texto, zoom, modos de cor e avisos para leitores de tela. Agentes: entre e escolha o padrão. MCP: servidores do repositório são aprovados no painel Git de um espaço de trabalho, e os agentes recebem as ferramentas do próprio Foreman. Espaços de trabalho remotos (experimentais, desativados por padrão) executam um espaço de trabalho em um sandbox na nuvem.',
  'tour.step.settings.where': 'a engrenagem na faixa de ícones de repositórios',
  'tour.step.help.title': 'Volte quando quiser',
  'tour.step.help.body': 'Repita este tour a partir daqui. Todo o resto está a uma busca: {palette} abre a paleta de comandos e {shortcuts} lista todos os atalhos.',
  'tour.step.help.where': 'o ? na faixa de ícones de repositórios',

